import os
from openai import OpenAI

def extract_receipt_data(image_path):
    """
    Extract structured receipt data using OpenAI's GPT-4 Vision API.

    Args:
        image_path: Path to receipt image file

    Returns:
        dict: Extracted receipt data including merchant, tax, total, and items
    """
    client = OpenAI(api_key=os.environ.get("OPENAI_API_KEY"))

    with open(image_path, "rb") as image_file:
        response = client.chat.completions.create(
            model="gpt-4-vision-preview",
            messages=[
                {
                    "role": "user",
                    "content": [
                        {"type": "text", "text": "Extract the following structured data from this receipt: merchant name, tax amount, total amount, and list of items with their names and prices. Return as valid JSON with keys: merchant, tax, total, items (list of objects with name and price)."},
                        {
                            "type": "image_url",
                            "image_url": {
                                "url": f"data:image/jpeg;base64,{image_file.read().encode('base64')}"
                            }
                        }
                    ]
                }
            ],
            max_tokens=500
        )

    import json
    extracted_data = json.loads(response.choices[0].message.content)

    return {
        "merchant": extracted_data.get("merchant", ""),
        "tax": extracted_data.get("tax", 0.0),
        "total": extracted_data.get("total", 0.0),
        "items": extracted_data.get("items", [])
    }
